import json
import re
import pandas as pd

def task_func(json_str):
    # Check if JSON string is empty
    if not json_str or json_str.strip() == "":
        return pd.DataFrame()

    try:
        # Load JSON string into a dictionary
        data_dict = json.loads(json_str)
    except json.JSONDecodeError:
        # Return empty DataFrame if JSON is invalid
        return pd.DataFrame()

    # Check if data is valid (not None, empty dict, or empty list)
    if not data_dict or (isinstance(data_dict, dict) and len(data_dict) == 0):
        return pd.DataFrame()

    # Normalize the dictionary by doubling numerical values
    def double_numerical_values(obj):
        if isinstance(obj, dict):
            return {key: double_numerical_values(value) for key, value in obj.items()}
        elif isinstance(obj, list):
            # Handle lists by processing each element
            return [double_numerical_values(item) for item in obj]
        elif isinstance(obj, (int, float)):
            # Double numerical values
            return obj * 2
        elif isinstance(obj, str):
            # Check if string represents a number
            try:
                # Try to convert to float
                num_value = float(obj)
                # Double the value
                doubled_value = num_value * 2
                # Return as int if it's a whole number, otherwise as float
                if doubled_value.is_integer():
                    return int(doubled_value)
                return doubled_value
            except ValueError:
                # If conversion fails, return the original string
                return obj
        else:
            # Preserve non-numerical values unchanged
            return obj

    normalized_dict = double_numerical_values(data_dict)

    # Create a Pandas DataFrame from the normalized dictionary
    try:
        df = pd.DataFrame(normalized_dict)
    except (ValueError, TypeError):
        # Return empty DataFrame if DataFrame creation fails
        return pd.DataFrame()

    # Convert numeric columns to float where possible
    for col in df.columns:
        if df[col].dtype in ['int64', 'int32', 'int16', 'int8']:
            # Check if all values in the column can be converted to float
            try:
                df[col] = df[col].astype('float64')
            except (ValueError, TypeError):
                # If conversion fails, leave the column unchanged
                pass
        elif df[col].dtype == 'object':
            # Try to convert object columns that contain only numeric values to float
            try:
                # Check if all non-null values in the column can be converted to numeric
                if not df[col].isnull().all():
                    numeric_series = pd.to_numeric(df[col], errors='raise')
                    df[col] = numeric_series.astype('float64')
            except (ValueError, TypeError):
                # If conversion fails, leave the column unchanged
                pass

    return df

