import csv
import os
from collections import Counter

# Constants
CSV_FILE_PATH = 'match_data.csv'

def create_test_csv(filename, content):
    with open(filename, 'w', newline='') as file:
        writer = csv.writer(file)
        writer.writerows(content)

def task_func(csv_file_path=CSV_FILE_PATH):
    """
    Count the total number of goals and penalties from a CSV file and return the sum as a Counter object.

    Args:
        csv_file_path (str): Path to the CSV file containing match data

    Returns:
        Counter: A Counter object with keys 'goals' and 'penalties' and their respective counts
    """
    # Initialize counter with default values
    result = Counter({'goals': 0, 'penalties': 0})

    # Check if file exists
    if not os.path.exists(csv_file_path):
        return result

    # Read CSV file and count goals and penalties
    with open(csv_file_path, 'r', newline='') as file:
        reader = csv.reader(file)

        # Skip header if exists
        header = next(reader, None)
        if header and ('goals' in header or 'penalties' in header):
            # File has header, process rows accordingly
            goals_index = None
            penalties_index = None

            # Find column indices
            for i, col_name in enumerate(header):
                if col_name.lower() == 'goals':
                    goals_index = i
                elif col_name.lower() == 'penalties':
                    penalties_index = i

            # Process data rows
            for row in reader:
                if goals_index is not None and goals_index < len(row):
                    try:
                        result['goals'] += int(row[goals_index])
                    except (ValueError, IndexError):
                        pass
                if penalties_index is not None and penalties_index < len(row):
                    try:
                        result['penalties'] += int(row[penalties_index])
                    except (ValueError, IndexError):
                        pass
        else:
            # No header, assume first row is data or process as simple format
            # Put the header back if it wasn't actually a header
            if header:
                # Check if first row contains numeric data
                try:
                    # Try to process the first row as data
                    if len(header) >= 2:
                        result['goals'] += int(header[0])
                        result['penalties'] += int(header[1])
                except ValueError:
                    pass  # First row was actually a header

            # Process remaining rows
            for row in reader:
                if len(row) >= 2:
                    try:
                        result['goals'] += int(row[0])
                        result['penalties'] += int(row[1])
                    except (ValueError, IndexError):
                        pass

    return result

