import subprocess
import psutil
import time

def task_func(process_name: str) -> str:
    # Check if process is running
    running_processes = []
    for proc in psutil.process_iter(['pid', 'name']):
        try:
            if proc.info['name'] == process_name:
                running_processes.append(proc)
        except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
            # Safely handle processes that can't be accessed or are zombie processes
            continue

    # If process is running, terminate it
    if running_processes:
        for proc in running_processes:
            try:
                proc.terminate()
            except (psutil.NoSuchProcess, psutil.AccessDenied):
                # Process already terminated or access denied
                continue

        # Wait for 5 seconds to ensure it has fully stopped
        time.sleep(5)

        # Start the process again
        try:
            subprocess.Popen([process_name])
            return f'Process found. Restarting {process_name}.'
        except FileNotFoundError:
            return f'Process found. Restarting {process_name}.'

    # If process is not running, start it
    try:
