from functools import reduce
from itertools import permutations
import math

def task_func(numbers):
    # Check if input is a list
    if not isinstance(numbers, list):
        raise TypeError("the input is not a list or if any element in the list is not an integer")

    # Check if all elements are integers
    for num in numbers:
        if not isinstance(num, int):
            raise TypeError("the input is not a list or if any element in the list is not an integer")

    # Check if any number is negative
    for num in numbers:
        if num < 0:
            raise ValueError("some numbers in list are negative.")

    # Handle empty list case
    if len(numbers) == 0:
        return [], []

    # Generate all permutations of the input list
    perms = list(permutations(numbers))

    # Calculate the sum of factorials for each permutation
    sums = []
    for perm in perms:
        factorial_sum = sum(math.factorial(num) for num in perm)
        sums.append(factorial_sum)

    return sums, perms

import subprocess
import psutil
import time
import os

def task_func(script_path: str, timeout=10) -> dict:
    # Check if the script path exists
    if not os.path.exists(script_path):
        raise FileNotFoundError("script path not found!")

    # Execute the script using subprocess
    process = subprocess.Popen(['bash', script_path], stdout=subprocess.PIPE, stderr=subprocess.PIPE)

    # Get the process ID
    pid = process.pid

    # Monitor CPU and memory usage
    cpu_usage_sum = 0.0
    memory_usage_max = 0
    sample_count = 0

    start_time = time.time()

    try:
        # Get the psutil process object
        ps_process = psutil.Process(pid)

        # Monitor until process completes or timeout
        while ps_process.is_running() and time.time() - start_time < timeout:
            try:
                # Get CPU usage percentage with 50ms interval
                cpu_percent = ps_process.cpu_percent(interval=0.05)
                cpu_usage_sum += cpu_percent
                sample_count += 1

                # Get memory usage in bytes
                memory_info = ps_process.memory_info()
                if memory_info.rss > memory_usage_max:
                    memory_usage_max = memory_info.rss

            except (psutil.NoSuchProcess, psutil.AccessDenied):
                # Process has terminated or we lost access
                break

    except psutil.NoSuchProcess:
        # Process has already terminated
        pass
    except Exception:
        # Handle other potential exceptions
        pass

    # Implement timeout mechanism
    if time.time() - start_time >= timeout:
        try:
            # Terminate the process if it's still running
            ps_process = psutil.Process(pid)
            ps_process.terminate()
            try:
                ps_process.wait(timeout=5)  # Give 5 seconds to terminate gracefully
            except psutil.TimeoutExpired:
                ps_process.kill()  # Force kill if it doesn't terminate gracefully
        except (psutil.NoSuchProcess, ProcessLookupError):
            # Process already terminated
            pass

    # Wait for process to complete (with timeout)
    try:
        process.wait(timeout=timeout)
    except subprocess.TimeoutExpired:
        # Kill the process if it's still running
        try:
            process.terminate()
            try:
                process.wait(timeout=5)  # Give 5 seconds to terminate gracefully
            except subprocess.TimeoutExpired:
                process.kill()  # Force kill if it doesn't terminate gracefully
        except ProcessLookupError:
            pass

    # Calculate average CPU usage
    avg_cpu_usage = cpu_usage_sum / sample_count if sample_count > 0 else 0.0

    # Return the results as a dictionary
    return {
        'CPU Usage': avg_cpu_usage,
        'Memory Usage': memory_usage_max
    }

