            while ps_process.is_running() and ps_process.status() != psutil.STATUS_ZOMBIE and time.time() - start_time < timeout:
                try:
                    # Get CPU usage percentage with 50ms interval
                    cpu_percent = ps_process.cpu_percent(interval=0.05)
                    cpu_usage_sum += cpu_percent
                    sample_count += 1

                    # Get memory usage in bytes
                    memory_info = ps_process.memory_info()
                    if memory_info.rss > memory_usage_max:
                        memory_usage_max = memory_info.rss

                except (psutil.NoSuchProcess, psutil.AccessDenied, psutil.ZombieProcess):
                    # Process has terminated, become a zombie, or we lost access
                    break

        except psutil.NoSuchProcess:
            # Process has already terminated
            pass
        except Exception:
            # Handle other potential exceptions
            pass

        # Calculate average CPU usage
        avg_cpu_usage = cpu_usage_sum / sample_count if sample_count > 0 else 0.0

        # Return the results as a dictionary
        return {
            'CPU Usage': avg_cpu_usage,
            'Memory Usage': memory_usage_max
        }

    finally:
        # Ensure the subprocess is properly terminated and waited upon
        if process is not None:
            try:
                # Check if process is still running
                if process.poll() is None:
                    # Implement timeout mechanism
                    start_time = time.time()
                    process.terminate()

                    # Wait for graceful termination
                    while process.poll() is None and time.time() - start_time < 5:
                        time.sleep(0.1)

                    # Force kill if still running
                    if process.poll() is None:
                        process.kill()
                        process.wait()
                else:
                    # Process already terminated, just wait to clean up
                    process.wait()
            except (OSError, subprocess.SubprocessError):
                # Process already terminated or other error
                try:
                    process.wait()
                except:
                    pass
            except Exception:
                # Handle any other unexpected exceptions
                pass

        # Also ensure psutil process is handled
        if ps_process is not None:
            try:
                if ps_process.is_running():
                    ps_process.terminate()
                    try:
                        ps_process.wait(timeout=5)
                    except psutil.TimeoutExpired:
                        ps_process.kill()
            except (psutil.NoSuchProcess, psutil.AccessDenied, ProcessLookupError):
                # Process already terminated or access denied
                pass
            except Exception:
                # Handle any other unexpected exceptions
                pass
