import json
import pandas as pd
import numpy as np

def task_func(input_file="data.json"):
    # Read the JSON file
    with open(input_file, 'r') as f:
        data = json.load(f)

    # Dictionary to store means and medians for each key
    stats = {}

    # Get all unique keys from all dictionaries
    all_keys = set()
    for item in data:
        all_keys.update(item.keys())

    # For each key, calculate the mean and median of numeric values
    for key in all_keys:
        # Collect all numeric values for this key
        numeric_values = []
        for item in data:
            if key in item:
                value = item[key]
                # Check if the value is numeric (int or float)
                if isinstance(value, (int, float)) and not isinstance(value, bool):
                    numeric_values.append(value)

        # Calculate mean and median if there are numeric values
        if numeric_values:
            stats[key] = {
                'mean': np.mean(numeric_values),
                'median': np.median(numeric_values)
            }

    # Create DataFrame with keys as index and 'mean' and 'median' columns
    result_df = pd.DataFrame.from_dict(stats, orient='index')

    return result_df

