import pandas as pd
import numpy as np

def task_func(data_list=[('a', 1, 2.1), ('b', 2, 3.2), ('c', 3, 4.3), ('d', 4, 5.4), ('e', 5, 6.5)]):
    # Handle empty list case
    if not data_list:
        return pd.DataFrame(columns=['Mean Value'])

    # Convert to numpy array for easier handling
    data_array = np.array(data_list)

    # Get number of positions (columns)
    num_positions = data_array.shape[1]

    # Initialize list to store means
    means = []

    # For each position, calculate mean of numeric values only
    for i in range(num_positions):
        # Extract values from this position
        position_values = data_array[:, i]

        # Filter only numeric values (int or float)
        numeric_values = []
        for val in position_values:
            try:
                # Check if value is numeric (int or float) but not boolean
                if isinstance(val, (int, float)) and not isinstance(val, bool):
                    numeric_values.append(float(val))
                # Try to convert string numbers to float
                elif isinstance(val, str):
                    try:
                        converted_val = float(val)
                        numeric_values.append(converted_val)
                    except ValueError:
                        continue
            except (ValueError, TypeError):
                continue

        # Calculate mean if there are numeric values, otherwise use NaN
        if numeric_values:
            means.append(np.mean(numeric_values))
        else:
            means.append(np.nan)

    # Create DataFrame
    df = pd.DataFrame({
        'Mean Value': means
    })

    # Set index to 'Position i' format
    df.index = [f'Position {i}' for i in range(len(means))]

    return df

