def task_func(df):
    """
    Calculate the mean and standard deviation for each column in the DataFrame.

    Parameters:
    df (pandas.DataFrame): The input DataFrame

    Returns:
    dict: A dictionary where each key is a column name and the value is a dictionary
          containing 'mean' and 'std' for that column
    """
    stats_dict = {}

    for column in df.columns:
        # Only calculate statistics for numeric columns
        if pd.api.types.is_numeric_dtype(df[column]):
            stats_dict[column] = {
                'mean': float(df[column].mean()),
                'std': float(df[column].std())
            }
        else:
            # For non-numeric columns, set mean and std to None or skip them
            stats_dict[column] = {
                'mean': None,
                'std': None
            }

    return stats_dict

